import {el} from '/shared/client.js';
// Switchback's pages. The shared Web Host serves this controller and forwards
// only the Agent tools the run's policy allows. Every page renders what one or
// more switchback.* tools return; the page holds no business rules and no
// business store. The only things kept in memory are the current route, the
// last search form, the hold or preview a checkout write just returned, and
// the outcome (receipt or error) of the last action, shown until the next one.

