    const say=h=>({confirmed:'Booked',checked_in:'Checked in',completed:'Stay completed',cancelled:'Cancelled'+(h.refund_cents!==undefined?', refund '+money(h.refund_cents):''),
      no_show_released:'Released as a no-show (no refund)',late_arrival_notice:'Late-arrival notice filed',closure_cancelled:'Cancelled by closure '+(h.closure_id||'')+', full refund',
      modified:h.from?`Changed from ${sname(h.from.site_id)}, ${stay(h.from.arrival,h.from.departure)}`:'Changed'}[h.action]||human(h.action));
    parts.push(el('h3',{},'History'),el('ol',{class:'sb-timeline'},...r.history.map(h=>el('li',{'data-history':h.action},el('span',{class:'sb-meta'},when(h.at,off)),el('span',{},say(h))))),
      el('h3',{},'Payments'),paymentTable(payments,cardOf,off));
