const PAYMENT={booking:'Booking',change:'Change',cancellation:'Cancellation',closure:'Closure'};
function paymentTable(payments,cardOf,off){
  return table(['Date','What','Amount','Card','Posts','Status'],payments.map(p=>el('tr',{'data-payment-id':p.id},el('td',{},when(p.created_at,off)),
    el('td',{},(p.kind==='refund'?'Refund: ':'Charge: ')+(PAYMENT[p.reason]||human(p.reason)).toLowerCase(),el('small',{class:'sb-id'},p.id)),el('td',{},money(p.amount_cents)),
    el('td',{},cardOf(p.card_id)?.label||p.card_id),el('td',{},when(p.posts_at,off)),el('td',{},human(p.status)))));
}

// ---- Router ----------------------------------------------------------------------
let renderTicket=0;
async function render(){
  const ticket=++renderTicket,[name,...args]=(location.hash.replace(/^#\/?/,'')||'search').split('/');
  const page=pages[name]?name:'search';
  nav.replaceChildren(...navItems.map(([id,label,ic])=>el('button',{type:'button','aria-current':id===page||(id==='reservations'&&['reservation','receipt'].includes(page))||(id==='search'&&['facility','site','checkout'].includes(page))?'page':false,onclick:()=>{flash=null;go('#/'+id);}},
    el('span',{class:'nav-symbol','aria-hidden':'true'},icon(ic)),el('span',{},label))));
  document.querySelector('#app').setAttribute('aria-busy','true');
  try{
    tools=(await request('/api/tools')).tools;
    pageTitle='Switchback';
    const content=await pages[page](args.map(decodeURIComponent));
    if(ticket!==renderTicket)return;
    main.dataset.page=page;main.replaceChildren(...[flashBox(),...content.flat()].filter(Boolean));
    document.title=pageTitle+' · Switchback';
    if(!status.dataset.error&&!flash)ok('Showing the latest state.');
  }catch(e){
    if(ticket!==renderTicket)return;
    // A page that cannot load (an unknown ID, a refused read) replaces the old
    // content, so nothing from the previous page is left looking current.
    const missing=e.code==='not_found';
    document.title=(missing?'Not found':'Could not load')+' · Switchback';
    main.dataset.page='error';
    main.replaceChildren(el('h2',{'data-page-title':'error'},missing?'Not found':'This page could not load'),errorBox(e),el('p',{},link('#/search','Back to search'),' · ',link('#/reservations','Your reservations')));
    status.dataset.error='true';status.dataset.errorCode=e.code||'request_failed';status.textContent=(e.code?e.code+': ':'')+e.message;
  }
  finally{if(ticket===renderTicket)document.querySelector('#app').setAttribute('aria-busy','false');}
}
window.addEventListener('hashchange',()=>{if(!ownNavigation)flash=null;ownNavigation=false;delete status.dataset.error;render();});
(async()=>{
  try{
    const token=new URLSearchParams(location.hash.slice(1)).get('access');
    if(token){history.replaceState(null,'',location.pathname+'#/search');({csrf}=await request('/session','POST',{token}));}
    else({csrf}=await request('/session'));
    await render();
  }catch(e){showError(e);}
})();
